-- FDA Drug manufacturing: eleven combined questions split (new DM20-DM32).
update public.hub_chk_points set q='Is the manufacturing licence (Form 25/28) valid?', why='Making any drug on a lapsed licence is treated as manufacture without licence.', law='Drugs & Cosmetics Act s.18(c); Drugs Rules r.70–76', evidence='Licence copy + latest retention fee receipt', updated_at=now() where code='DM01';
update public.hub_chk_points set q='Are the approved manufacturing chemist and analytical chemist the same people named on the licence?', why='Inspectors first check the technical staff. A missing person can suspend the licence.', law='Drugs Rules r.71(1), r.76; G.S.R. 135(E) 2026', evidence='Staff endorsement letter', updated_at=now() where code='DM03';
update public.hub_chk_points set q='Is every finished batch tested and released by QC?', why='A failed sample in the market leads to prosecution of the proprietor.', law='Drugs Rules r.74, r.78; Schedule M', evidence='Batch release register', updated_at=now() where code='DM06';
update public.hub_chk_points set q='Do all labels carry the product name, batch number and Mfg/Exp dates?', why='A wrong label makes the drug ''misbranded'' even if quality is perfect.', law='Drugs Rules r.96, r.97', evidence='Approved label artwork file', updated_at=now() where code='DM07';
update public.hub_chk_points set q='Is the revised Schedule M gap assessment done?', why='Revised Schedule M applies to every unit from 1 Jan 2026. Inspections are risk-based now.', law='Schedule M (G.S.R. 922(E) 2023)', evidence='Gap assessment', updated_at=now() where code='DM09';
update public.hub_chk_points set q='Is there a written recall procedure?', why='On a quality failure we must be able to pull back stock fast.', law='Schedule M; CDSCO recall guidelines', evidence='Recall SOP', updated_at=now() where code='DM12';
update public.hub_chk_points set q='Is a pharmacovigilance officer named?', why='This is now a licence condition under Schedule M.', law='Schedule M; CDSCO circular 3 Jun 2026', evidence='PV SOP', updated_at=now() where code='DM14';
update public.hub_chk_points set q='Is the inspection book (Form 35) available?', why='Open remarks from the last visit are the first thing checked in the next one.', law='Drugs Rules r.74(j)', evidence='Inspection book', updated_at=now() where code='DM16';
update public.hub_chk_points set q='For any third-party or loan-licence manufacturing, do we hold the signed agreement?', why='We remain responsible for the product sold under our name.', law='Drugs Rules r.69A, r.75A', evidence='Signed agreement', updated_at=now() where code='DM17';
update public.hub_chk_points set q='Are the NDPS / controlled-substance licences valid?', why='NDPS shortage or excess is a criminal offence with jail.', law='NDPS Act 1985; Punjab NDPS Rules', evidence='NDPS licence', updated_at=now() where code='DM18';
update public.hub_chk_points set q='Is the excise permit for rectified spirit / ethanol valid?', why='Excise shortage brings heavy penalty and can stop supply.', law='Punjab Excise Act; M&TP Act', evidence='Permit', updated_at=now() where code='DM19';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM20','FDA – Drug manufacturing','Is the manufacturing licence displayed?','Inspectors expect the licence on display at the premises.','Drugs & Cosmetics Act s.18(c); Drugs Rules r.70–76','drug_mfg',array['fda']::text[],'M','Photo of displayed licence',9920,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM21','FDA – Drug manufacturing','Does the licence cover every section and dosage form we make?','Making any drug outside the licence is treated as manufacture without licence.','Drugs & Cosmetics Act s.18(c); Drugs Rules r.70–76','drug_mfg',array['fda']::text[],'H','Licence sections against product list',9921,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM22','FDA – Drug manufacturing','Are the approved manufacturing chemist and analytical chemist present daily?','Inspectors first check the technical staff. A missing person can suspend the licence.','Drugs Rules r.71(1), r.76; G.S.R. 135(E) 2026','drug_mfg',array['fda']::text[],'H','Attendance record',9922,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM23','FDA – Drug manufacturing','Do all labels carry the licence number and MRP?','A wrong label makes the drug ''misbranded'' even if quality is perfect.','Drugs Rules r.96, r.97','drug_mfg',array['fda']::text[],'H','Approved label artwork file',9923,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM24','FDA – Drug manufacturing','Do all labels carry the correct Schedule H/G warning?','A wrong label makes the drug ''misbranded'' even if quality is perfect.','Drugs Rules r.96, r.97','drug_mfg',array['fda']::text[],'H','Approved label artwork file',9924,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM25','FDA – Drug manufacturing','Was a mock recall done in the last 2 years?','On a quality failure we must be able to pull back stock fast.','Schedule M; CDSCO recall guidelines','drug_mfg',array['fda']::text[],'M','Mock recall report',9925,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM26','FDA – Drug manufacturing','Are side-effect reports sent to PvPI?','This is now a licence condition under Schedule M.','Schedule M; CDSCO circular 3 Jun 2026','drug_mfg',array['fda']::text[],'M','ADR log',9926,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM27','FDA – Drug manufacturing','Are all past inspection remarks closed in writing?','Open remarks from the last visit are the first thing checked in the next one.','Drugs Rules r.74(j)','drug_mfg',array['fda']::text[],'H','Compliance replies',9927,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM28','FDA – Drug manufacturing','For any third-party or loan-licence manufacturing, do we hold the other party''s valid licence?','We remain responsible for the product sold under our name.','Drugs Rules r.69A, r.75A','drug_mfg',array['fda']::text[],'M','Licence copies',9928,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM29','FDA – Drug manufacturing','Are the daily stock registers for NDPS / controlled substances complete and tallied?','NDPS shortage or excess is a criminal offence with jail.','NDPS Act 1985; Punjab NDPS Rules','ndps',array['fda']::text[],'H','Stock register',9929,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM30','FDA – Drug manufacturing','Does the rectified spirit / ethanol stock register tally?','Excise shortage brings heavy penalty and can stop supply.','Punjab Excise Act; M&TP Act','alcohol',array['fda']::text[],'H','Spirit register',9930,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM31','FDA – Drug manufacturing','Are control samples kept for every batch?','A failed sample in the market leads to prosecution of the proprietor.','Drugs Rules r.74, r.78; Schedule M','drug_mfg',array['fda']::text[],'H','Control sample log',9931,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('DM32','FDA – Drug manufacturing','Are all Schedule M gaps being closed, with dates?','Revised Schedule M applies to every unit from 1 Jan 2026. Inspections are risk-based now.','Schedule M (G.S.R. 922(E) 2023)','drug_mfg',array['fda']::text[],'H','Action plan',9932,true,null) on conflict (code) do nothing;
